// spec: specs/orders.md §29 · кейс .qa/tests/orders/ord-42-tabs-active-style.md (+ ord-41 регресс #0f04ee)
// seed: tests/seed.admin.spec.ts
// #455fa4 (עבר QA 28.10): вкладки /orders («הכל / ממתינות לאישור / אושרו / נדחו») и /catalog («הכל · זמינים · לא זמינים»):
//   активная — надпись и число primary rgb(53,71,121), вес 600 (Figma Tab/Active SemiBold), border-bottom 1px primary;
//   неактивные — вес 500 (Figma Tab/Label Medium), штрих прозрачный (своего штриха нет); штрих переходит при клике;
//   при переключении ряд не прыгает (высота/верх ряда и вкладок те же). /orders 320–414 — без прокрутки вбок (регресс #0f04ee).
// У вкладок transition-colors 150мс — замеры через expect.poll до установившегося значения, без пауз.
// Только просмотр (клики по вкладкам, фильтр месяца не трогаем) → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

const PRIMARY = 'rgb(53, 71, 121)';
const TRANSPARENT = 'rgba(0, 0, 0, 0)';
const ORDER_TABS = ['הכל', 'ממתינות לאישור', 'אושרו', 'נדחו'];
const CATALOG_TABS = ['הכל', 'זמינים', 'לא זמינים'];

const tab = (page: Page, name: string) => page.locator('button[aria-current]').filter({ hasText: new RegExp(`^${name}\\d+$`) });

/** Состояние ряда вкладок: стиль кнопки (надпись) и числа отдельно, штрих, положение. */
const measure = (page: Page) => page.evaluate(() => {
  const first = [...document.querySelectorAll('button[aria-current]')].find((e) => /^הכל\d/.test(e.textContent!.trim()))!;
  const row = first.parentElement!;
  const r = row.getBoundingClientRect();
  const tabs = [...row.querySelectorAll(':scope > button')].map((b) => {
    const cs = getComputedStyle(b);
    const num = [...b.querySelectorAll('span')].find((s) => /^\d+$/.test(s.textContent!.trim()));
    const ns = num ? getComputedStyle(num) : null;
    const bb = b.getBoundingClientRect();
    return {
      text: b.textContent!.trim(), current: b.getAttribute('aria-current'),
      color: cs.color, weight: cs.fontWeight, bbWidth: cs.borderBottomWidth, bbStyle: cs.borderBottomStyle, bbColor: cs.borderBottomColor,
      numColor: ns?.color ?? null, numWeight: ns?.fontWeight ?? null, top: bb.top, height: bb.height,
    };
  });
  return { vw: innerWidth, docSW: document.documentElement.scrollWidth, rowSW: row.scrollWidth, rowCW: row.clientWidth, rowTop: r.top, rowHeight: r.height, tabs };
});
type M = Awaited<ReturnType<typeof measure>>;

/** Нарушения стиля при активной вкладке `active` (пустой список — всё по требованию). */
function violations(m: M, names: string[], active: number): string[] {
  const out: string[] = [];
  if (m.tabs.length !== names.length) return [`вкладок ${m.tabs.length}, ожидалось ${names.length}`];
  m.tabs.forEach((t, i) => {
    const n = names[i];
    if (!new RegExp(`^${n}\\d+$`).test(t.text)) out.push(`вкладка ${i + 1}: «${t.text}» — нет «${n}» с числом`);
    if (t.numColor === null) out.push(`«${n}»: число не найдено`);
    if (t.bbWidth !== '1px' || t.bbStyle !== 'solid') out.push(`«${n}»: border-bottom ${t.bbWidth} ${t.bbStyle} (ожидалось 1px solid — без скачка высоты)`);
    if (i === active) {
      if (t.current !== 'true') out.push(`«${n}»: aria-current=${t.current}`);
      if (t.color !== PRIMARY) out.push(`активная «${n}»: цвет надписи ${t.color}`);
      if (t.numColor !== PRIMARY) out.push(`активная «${n}»: цвет числа ${t.numColor}`);
      if (t.weight !== '600') out.push(`активная «${n}»: вес надписи ${t.weight}`);
      if (t.numWeight !== '600') out.push(`активная «${n}»: вес числа ${t.numWeight}`);
      if (t.bbColor !== PRIMARY) out.push(`активная «${n}»: штрих ${t.bbColor}`);
    } else {
      if (t.current !== 'false') out.push(`«${n}»: aria-current=${t.current}`);
      if (t.weight !== '500') out.push(`неактивная «${n}»: вес надписи ${t.weight}`);
      if (t.numWeight !== '500') out.push(`неактивная «${n}»: вес числа ${t.numWeight}`);
      if (t.color === PRIMARY || t.numColor === PRIMARY) out.push(`неактивная «${n}»: цвет primary`);
      if (t.bbColor !== TRANSPARENT) out.push(`неактивная «${n}»: свой штрих ${t.bbColor}`);
    }
  });
  return out;
}

/** Ждём окончания transition-colors (~150мс) — пока нарушения не исчезнут. */
async function expectActive(page: Page, names: string[], active: number, tag: string) {
  await expect.poll(async () => violations(await measure(page), names, active), { message: `${tag}: активная «${names[active]}»`, timeout: 5_000 }).toEqual([]);
  return measure(page);
}

function expectNoJump(before: M, after: M, tag: string) {
  expect(Math.abs(after.rowTop - before.rowTop), `${tag}: верх ряда не сдвинулся`).toBeLessThanOrEqual(0.5);
  expect(Math.abs(after.rowHeight - before.rowHeight), `${tag}: высота ряда та же`).toBeLessThanOrEqual(0.5);
  after.tabs.forEach((t, i) => {
    expect(Math.abs(t.top - before.tabs[i].top), `${tag}: «${t.text}» по вертикали на месте`).toBeLessThanOrEqual(0.5);
    expect(Math.abs(t.height - before.tabs[i].height), `${tag}: высота «${t.text}» та же`).toBeLessThanOrEqual(0.5);
  });
}

function expectNoHScroll(m: M, tag: string) {
  expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  expect(m.rowSW, `${tag}: ряд вкладок без прокрутки вбок`).toBeLessThanOrEqual(m.rowCW + 1);
}

async function openOrders(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  for (const n of ORDER_TABS) await expect(tab(page, n), `«${n}» с числом`).toBeVisible({ timeout: 30_000 });
}

async function openCatalog(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  for (const n of CATALOG_TABS) await expect(tab(page, n), `«${n}» с числом`).toBeVisible({ timeout: 30_000 });
}

/** Клик по каждой вкладке по очереди и обратно на «הכל»: стиль, штрих переходит, ряд не прыгает. */
async function cycleTabs(page: Page, names: string[], tag: string, checkJump = true) {
  let prev = await expectActive(page, names, 0, `${tag} старт`);
  for (const i of [...names.keys()].slice(1).concat(0)) {
    await tab(page, names[i]).click();
    const m = await expectActive(page, names, i, tag);
    if (checkJump) expectNoJump(prev, m, `${tag}: → «${names[i]}»`);
    prev = m;
  }
}

test.describe('orders/catalog — לשונית פעילה: טקסט ומספר primary, משקל 600, קו תחתון primary; לא פעילות 500 בלי קו (#455fa4)', () => {
  test('/orders 1440: בכל לשונית פעילה — טקסט+מספר rgb(53,71,121) 600, קו 1px primary; אחרות 500, קו שקוף; הקו עובר בלחיצה, השורה לא קופצת #455fa4 @desktop @orders @prod-safe', async ({ page }) => {
    await openOrders(page);
    await cycleTabs(page, ORDER_TABS, '/orders 1440');
  });

  test('/catalog 1440: אותו סגנון ל«הכל · זמינים · לא זמינים», הקו עובר בלחיצה, השורה לא קופצת #455fa4 @desktop @catalog @prod-safe', async ({ page }) => {
    await openCatalog(page);
    await cycleTabs(page, CATALOG_TABS, '/catalog 1440');
  });

  test('/orders 320–414: בלי גלילה לרוחב בכל לשונית פעילה (משקל 600 רחב יותר); 360–414 השורה לא קופצת; 320 — שבירה מותרת #455fa4 #0f04ee @iphone @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await page.setViewportSize({ width: 360, height: 740 });
    await openOrders(page);
    for (const [w, h] of [[320, 640], [360, 740], [375, 812], [390, 844], [414, 896]] as const) {
      await page.setViewportSize({ width: w, height: h });
      await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
      await tab(page, 'הכל').click();
      let prev = await expectActive(page, ORDER_TABS, 0, `${w}`);
      expectNoHScroll(prev, `${w}, «הכל»`);
      for (const i of [1, 2, 3, 0]) {
        await tab(page, ORDER_TABS[i]).click();
        const m = await expectActive(page, ORDER_TABS, i, `${w}`);
        expectNoHScroll(m, `${w}, «${ORDER_TABS[i]}»`);
        if (w >= 360) expectNoJump(prev, m, `${w}: → «${ORDER_TABS[i]}»`);
        prev = m;
      }
    }
  });

  test.describe('נציג', () => {
    test.use({ storageState: auth('rep') });
    test('נציג /orders 1440: אותו רכיב — «הכל» פעילה primary 600 עם קו, מעבר ל«אושרו» מעביר את הקו #455fa4 @desktop @orders @prod-safe', async ({ page }) => {
      await openOrders(page);
      await expectActive(page, ORDER_TABS, 0, 'rep /orders');
      await tab(page, 'אושרו').click();
      await expectActive(page, ORDER_TABS, 2, 'rep /orders');
    });
  });
});
